const labels={user_count:"已注册用户",enterprise_count:"已注册企业",pilot_count:"已注册飞手",order_count:"订单总数",open_order_count:"进行中订单",job_count:"招募信息",open_job_count:"招聘中岗位",application_count:"面试申请",device_total:"设备总数",available_device_count:"可租设备",rental_order_count:"租赁订单",renting_device_count:"在租设备"};

function getUser(){try{return JSON.parse(localStorage.getItem("fl_user")||"null")}catch{return null}}
function logout(){localStorage.removeItem("fl_token");localStorage.removeItem("fl_user");location.replace("/login")}
const authHeaders=()=>({Authorization:`Bearer ${localStorage.getItem("fl_token")||""}`,"Content-Type":"application/json"});
const escapeHtml=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
const dateSelects=value=>{const date=value?new Date(value):null,selectedYear=date&&!Number.isNaN(date.valueOf())?date.getFullYear():'',selectedMonth=date&&!Number.isNaN(date.valueOf())?date.getMonth()+1:'',selectedDay=date&&!Number.isNaN(date.valueOf())?date.getDate():'';const now=new Date().getFullYear(),option=(value,label,selected)=>`<option value="${value}" ${String(value)===String(selected)?'selected':''}>${label}</option>`;return `<div class="admin-date-selects" data-valid-until><select data-date-year>${option('','年',selectedYear)}${Array.from({length:7},(_,i)=>option(now+i,`${now+i}年`,selectedYear)).join('')}</select><select data-date-month>${option('','月',selectedMonth)}${Array.from({length:12},(_,i)=>option(i+1,`${i+1}月`,selectedMonth)).join('')}</select><select data-date-day>${option('','日',selectedDay)}${Array.from({length:31},(_,i)=>option(i+1,`${i+1}日`,selectedDay)).join('')}</select></div>`};

async function loadReviews(){
  const host=document.querySelector("#review-orders");host.innerHTML='<p class="admin-loading">正在加载待审核订单……</p>';
  try{
    const response=await fetch("/api/orders/?status=submitted",{headers:authHeaders()});
    if(!response.ok)throw new Error("待审核订单加载失败");
    const payload=await response.json(),orders=payload.results||payload;
    host.innerHTML="";
    if(!orders.length){host.innerHTML='<p class="admin-empty">当前没有待审核作业。</p>';return}
    for(const order of orders){
      const row=document.createElement("article");row.className="review-order";
      row.innerHTML=`<div><strong>${order.order_no}</strong><p>${order.location} · ${order.pilot_name||"未知飞手"}</p><small>预算 ¥${Number(order.budget).toFixed(2)} · 提交于 ${order.submitted_at?new Date(order.submitted_at).toLocaleString("zh-CN",{hour12:false}):"—"}</small></div>`;
      const approve=document.createElement("button");approve.type="button";approve.textContent="审核通过";approve.addEventListener("click",async()=>{if(!confirm("确认该作业成果审核通过？"))return;const result=await fetch(`/api/orders/${order.id}/admin_review/`,{method:"POST",headers:authHeaders(),body:"{}"});if(!result.ok){const data=await result.json().catch(()=>({}));alert(data.detail||"审核失败");return}loadReviews()});
      row.append(approve);host.append(row);
    }
  }catch(error){host.innerHTML=`<p class="admin-error">${error.message}</p>`}
}

async function loadDashboard(){
  const user=getUser();
  const token=localStorage.getItem("fl_token")||"";
  if(!token||user?.role!=="admin"){logout();return}
  document.querySelector("#admin-name").textContent=`${user.username||"管理员"} · 平台管理员`;
  try{
    const response=await fetch("/api/common/admin-stats/",{headers:{Authorization:`Bearer ${token}`}});
    if(response.status===401||response.status===403){logout();return}
    if(!response.ok)throw new Error("管理员数据加载失败，请稍后重试。");
    const stats=await response.json();
    const container=document.querySelector("#admin-stats");
    container.innerHTML=`<div class="admin-summary-table"><div class="summary-row summary-head"><span>业务板块</span><span>总量</span><span>当前状态</span><span>管理入口</span></div><div class="summary-row"><strong>用户与资质</strong><span>${stats.user_count??0} 人</span><span>企业 ${stats.enterprise_count??0} · 飞手 ${stats.pilot_count??0}</span><span>用户与资质审核</span></div><div class="summary-row"><strong>作业订单</strong><span>${stats.order_count??0} 单</span><span>进行中 ${stats.open_order_count??0}</span><span>订单监管</span></div><div class="summary-row"><strong>招聘业务</strong><span>${stats.job_count??0} 条</span><span>招聘中 ${stats.open_job_count??0} · 申请 ${stats.application_count??0}</span><span>业务数据汇总</span></div><div class="summary-row"><strong>设备租赁</strong><span>${stats.device_total??0} 台</span><span>可租 ${stats.available_device_count??0} · 在租 ${stats.renting_device_count??0}</span><span>资金管理</span></div></div>`;
    document.querySelector("#admin-status").hidden=true;container.hidden=false;
    loadReviews();
    loadWorkspace();
  }catch(error){const status=document.querySelector("#admin-status");status.className="admin-error";status.textContent=error.message}
}

async function loadWorkspace(){
  try{
    const response=await fetch('/api/common/admin-workspace/',{headers:authHeaders()});
    if(!response.ok)throw new Error('管理工作台加载失败');
    const data=await response.json();
    data.users=Array.isArray(data.users)?data.users:[];data.orders=Array.isArray(data.orders)?data.orders:[];data.finance=data.finance||{transactions:[]};data.alerts=Array.isArray(data.alerts)?data.alerts:[];data.audit_logs=Array.isArray(data.audit_logs)?data.audit_logs:[];data.risk_config=data.risk_config||{sensitive_keywords:['机场','军用','禁飞','政府'],urgent_manual_review:true,weather_mode:'simulated'};data.withdrawals=Array.isArray(data.withdrawals)?data.withdrawals:[];data.invoices=Array.isArray(data.invoices)?data.invoices:[];
    document.querySelector('#admin-users').innerHTML=data.users.map(user=>`<article class="admin-review-record"><div class="admin-table-row"><div><strong>${escapeHtml(user.display_name)}</strong><small>${escapeHtml(user.username)} · ${user.role==='pilot'?'飞手':'需求企业'}</small></div><span>${escapeHtml(user.phone||'未绑定手机')}</span><span class="admin-state ${user.verified?'pass':'fail'}">${user.verified?'已认证':escapeHtml(user.review_status==='rejected'?'已驳回':'待审核')}</span><div class="admin-row-actions"><button data-verify-user="${user.id}" data-verified="false">通过</button><button class="danger" data-reject-user="${user.id}">驳回</button>${user.role==='pilot'?`<button data-pilot-policy="${user.id}">权限</button>`:''}</div></div>${user.review_reason?`<p class="admin-reason">上次驳回原因：${escapeHtml(user.review_reason)}</p>`:''}<div class="admin-documents">${Object.entries(user.documents||{}).map(([name,url])=>url?`<a href="${escapeHtml(url)}" target="_blank" rel="noreferrer">查看${escapeHtml(name)}</a>`:`<span>${escapeHtml(name)}：未提交</span>`).join('')}</div></article>`).join('')||'<p class="admin-empty">暂无用户</p>';
    document.querySelector('#admin-orders').innerHTML=data.orders.map(order=>`<article class="admin-table-row"><div><strong>${escapeHtml(order.order_no)}</strong><small>${escapeHtml(order.location)} · 风险 ${escapeHtml(order.risk_level||'low')}</small></div><span>${escapeHtml(order.enterprise_name)} / ${escapeHtml(order.pilot_name||'待接单')}</span><span class="admin-state">${escapeHtml(order.status_display)}</span><div>${order.status==='pending_review'?`<button data-publish-review="${order.id}" data-approved="true">通过发布</button><button class="danger" data-publish-review="${order.id}" data-approved="false">驳回</button>`:['disputed','aborted'].includes(order.status)?`<button data-resolve-dispute="${order.id}">处理</button>`:`<a href="/orders/${order.id}">查看</a>`}</div></article>`).join('');
    document.querySelector('#admin-airspace').innerHTML=data.orders.map(order=>`<article class="admin-compliance-row"><div><strong>${escapeHtml(order.order_no)}</strong><small>${escapeHtml(order.location)} · ${escapeHtml(order.work_type_display)}</small></div><label><input type="checkbox" data-airspace ${order.airspace_approved?'checked':''}>空域通过</label><label><input type="checkbox" data-weather ${order.weather_safe?'checked':''}>天气通过（6小时有效）</label><label>最高高度（米）<input type="number" data-altitude min="0" value="${escapeHtml(order.max_flight_altitude||'')}"></label><label>空域有效日期${dateSelects(order.airspace_valid_until)}</label><label class="wide">审批依据/意见<input data-review-note value="${escapeHtml(order.airspace_review_note||'')}" placeholder="填写批复编号、限制条件或驳回原因"></label><button data-save-compliance="${order.id}">保存复核</button></article>`).join('');
    document.querySelector('#admin-finance').innerHTML=`<div class="admin-finance-grid"><article><span>当前托管金额</span><strong>¥${Number(data.finance.escrow_total).toFixed(2)}</strong></article><article><span>飞手累计收入</span><strong>¥${Number(data.finance.pilot_income_total).toFixed(2)}</strong></article><article><span>平台及中介费</span><strong>¥${(Number(data.finance.platform_fee_total)+Number(data.finance.agency_fee_total)).toFixed(2)}</strong></article><article><span>租赁业务收入</span><strong>¥${Number(data.finance.rental_income_total).toFixed(2)}</strong></article></div><div class="admin-finance-ledger"><div class="ledger-row head"><span>业务单号</span><span>类型</span><span>金额</span><span>状态</span><span>更新时间</span></div>${(data.finance.transactions||[]).map(item=>`<div class="ledger-row"><strong>${escapeHtml(item.order_no)}</strong><span>${escapeHtml(item.business)}</span><span>¥${Number(item.amount).toFixed(2)}</span><span>${escapeHtml(item.status)}</span><span>${item.updated_at?new Date(item.updated_at).toLocaleString('zh-CN',{hour12:false}):'—'}</span></div>`).join('')}</div>`;
    document.querySelector('#admin-finance').insertAdjacentHTML('beforeend',`<h3>待处理资金申请</h3>${[...(data.withdrawals||[]).map(x=>({...x,kind:'withdrawal'})),...(data.invoices||[]).map(x=>({...x,kind:'invoice'}))].filter(x=>x.status==='pending').map(x=>`<article class="admin-table-row"><strong>${x.kind==='withdrawal'?'提现':'开票'} #${x.id}</strong><span>¥${Number(x.amount).toFixed(2)}</span><span>待审核</span><div><button data-finance-review="${x.kind}" data-id="${x.id}" data-approved="true">通过</button><button class="danger" data-finance-review="${x.kind}" data-id="${x.id}" data-approved="false">驳回</button></div></article>`).join('')||'<p class="admin-empty">暂无待处理申请</p>'}`);
    document.querySelector('#admin-risk').innerHTML=`<div class="admin-risk-config"><strong>当前模拟风控规则</strong><p>敏感词：${escapeHtml((data.risk_config.sensitive_keywords||[]).join('、'))} · 紧急订单人工复核 · 天气模式：模拟</p><button data-risk-config>修改模拟规则</button></div><h3>风险告警</h3>${(data.alerts||[]).map(x=>`<article class="admin-table-row"><strong>${escapeHtml(x.title)}</strong><span>${escapeHtml(x.content)}</span><span class="admin-state ${x.level==='high'?'fail':''}">${escapeHtml(x.level)}</span><a href="${x.link}">查看</a></article>`).join('')||'<p class="admin-empty">暂无风险告警</p>'}<h3>最近操作日志</h3>${(data.audit_logs||[]).map(x=>`<article class="admin-table-row"><strong>${escapeHtml(x.action)}</strong><span>${escapeHtml(x.target_type)} #${escapeHtml(x.target_id)}</span><span>${new Date(x.created_at).toLocaleString('zh-CN',{hour12:false})}</span><span></span></article>`).join('')||'<p class="admin-empty">暂无日志</p>'}<div class="admin-rule-modal" data-rule-modal hidden><form class="admin-rule-dialog"><div class="dialog-head"><div><small>SIMULATED RISK RULES</small><h2>修改模拟风控规则</h2></div><button type="button" data-close-rule>关闭</button></div><label>敏感空域关键词<span>多个关键词请使用中文或英文逗号分隔</span><textarea name="keywords" rows="4">${escapeHtml((data.risk_config.sensitive_keywords||[]).join('，'))}</textarea></label><label class="rule-check"><input name="urgent" type="checkbox" ${data.risk_config.urgent_manual_review!==false?'checked':''}>紧急订单必须人工复核</label><div class="rule-note">天气检查固定使用平台内模拟结果，不连接真实天气服务。</div><div class="rule-actions"><button type="button" data-close-rule>取消</button><button type="submit">保存规则</button><span aria-live="polite"></span></div></form></div>`;
    document.querySelectorAll('[data-save-compliance]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('.admin-compliance-row'),year=row.querySelector('[data-date-year]').value,month=row.querySelector('[data-date-month]').value,day=row.querySelector('[data-date-day]').value,date=year&&month&&day?`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`:'';if((year||month||day)&&!date){alert('请完整选择年、月、日');return}button.disabled=true;try{const result=await fetch(`/api/orders/${button.dataset.saveCompliance}/compliance-review/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({airspace_approved:row.querySelector('[data-airspace]').checked,weather_safe:row.querySelector('[data-weather]').checked,max_flight_altitude:row.querySelector('[data-altitude]').value||null,airspace_valid_until:date?`${date}T23:59:59+08:00`:null,review_note:row.querySelector('[data-review-note]').value})});if(!result.ok)throw new Error('复核保存失败');button.textContent='已保存';setTimeout(()=>button.textContent='保存复核',1200)}catch(error){alert(error.message)}finally{button.disabled=false}}));
    document.querySelectorAll('[data-verify-user]').forEach(button=>button.addEventListener('click',async()=>{const next=button.dataset.verified!=='true';if(!confirm(next?'确认该用户资质审核通过？':'确认撤销该用户认证？'))return;const result=await fetch(`/api/common/admin-users/${button.dataset.verifyUser}/verify/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({verified:next})});if(!result.ok){alert('资质审核保存失败');return}loadWorkspace()}));
    document.querySelectorAll('[data-reject-user]').forEach(button=>button.addEventListener('click',async()=>{const reason=prompt('请填写驳回原因（用户会在认证中心看到）：');if(!reason?.trim())return;const result=await fetch(`/api/common/admin-users/${button.dataset.rejectUser}/verify/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({verified:false,reason:reason.trim()})});if(!result.ok){alert('驳回保存失败');return}loadWorkspace()}));
    document.querySelectorAll('[data-publish-review]').forEach(button=>button.addEventListener('click',async()=>{const approved=button.dataset.approved==='true',reason=approved?'':prompt('请填写驳回原因：');if(!approved&&!reason?.trim())return;const result=await fetch(`/api/orders/${button.dataset.publishReview}/publish-review/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({approved,reason})});if(!result.ok){const body=await result.json().catch(()=>({}));alert(body.detail||'审核失败');return}loadWorkspace()}));
    document.querySelectorAll('[data-finance-review]').forEach(button=>button.addEventListener('click',async()=>{const approved=button.dataset.approved==='true';await fetch(`/api/common/admin-finance/${button.dataset.financeReview}/${button.dataset.id}/review/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({approved,reason:approved?'模拟审核通过':'模拟审核驳回'})});loadWorkspace()}));
    document.querySelectorAll('[data-pilot-policy]').forEach(button=>button.addEventListener('click',async()=>{const scope=prompt('输入允许作业类型（英文逗号分隔，如 plant,inspect,aerial；留空表示不限）：','');if(scope===null)return;const suspended=confirm('是否暂停该飞手派单？选择“取消”表示保持可派单。');const reason=suspended?(prompt('请输入暂停原因：')||'管理员模拟暂停派单'):'';await fetch(`/api/common/admin-pilots/${button.dataset.pilotPolicy}/policy/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({authorized_work_types:scope.split(',').map(x=>x.trim()).filter(Boolean),dispatch_suspended:suspended,suspension_reason:reason})});loadWorkspace()}));
    document.querySelectorAll('[data-resolve-dispute]').forEach(button=>button.addEventListener('click',async()=>{const result=prompt('输入处理结果：refund（退款）、rectify（整改）或 settle（继续结算）','rectify');if(!result)return;const note=prompt('填写处理意见：')||'';const response=await fetch(`/api/orders/${button.dataset.resolveDispute}/resolve-dispute/`,{method:'POST',headers:authHeaders(),body:JSON.stringify({result,note})});if(!response.ok){const body=await response.json().catch(()=>({}));alert(body.detail||'处理失败');return}loadWorkspace()}));
    const ruleModal=document.querySelector('[data-rule-modal]'),ruleForm=ruleModal?.querySelector('form');document.querySelector('[data-risk-config]')?.addEventListener('click',()=>ruleModal.hidden=false);ruleModal?.querySelectorAll('[data-close-rule]').forEach(button=>button.addEventListener('click',()=>ruleModal.hidden=true));ruleModal?.addEventListener('click',event=>{if(event.target===ruleModal)ruleModal.hidden=true});ruleForm?.addEventListener('submit',async event=>{event.preventDefault();const status=ruleForm.querySelector('[aria-live]'),keywords=ruleForm.keywords.value.split(/[，,]/).map(x=>x.trim()).filter(Boolean);status.textContent='正在保存……';const response=await fetch('/api/common/admin-risk-config/',{method:'POST',headers:authHeaders(),body:JSON.stringify({sensitive_keywords:keywords,urgent_manual_review:ruleForm.urgent.checked})});if(!response.ok){status.textContent='保存失败';return}status.textContent='保存成功';setTimeout(()=>loadWorkspace(),500)});
  }catch(error){document.querySelectorAll('.admin-workspace>div:last-child').forEach(host=>host.innerHTML=`<p class="admin-error">${escapeHtml(error.message)}</p>`)}
}

document.querySelectorAll('[data-admin-tab]').forEach(button=>button.addEventListener('click',()=>{
  document.querySelectorAll('[data-admin-tab]').forEach(item=>item.classList.toggle('active',item===button));
  document.querySelectorAll('[data-admin-panel]').forEach(panel=>panel.hidden=panel.dataset.adminPanel!==button.dataset.adminTab);
  document.querySelector('#admin-stats').hidden=button.dataset.adminTab!=='overview';
  const compact=document.querySelector('#compact-operation-overview');if(compact)compact.hidden=button.dataset.adminTab!=='overview';
}));

document.querySelector("#logout").addEventListener("click",logout);
document.querySelector("#refresh-review").addEventListener("click",loadReviews);
loadDashboard();
